(async () => {
  const d = new Date();
  const localDate = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const response = await fetch('/api/v1/dev/test-fixtures/performance/reference-scale-v1', {
    method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ local_date: localDate })
  });
  if (!response.ok) throw new Error(`reference fixture returned ${response.status}`);
  const result = await response.json();
  const expected = { work_items: 1000, calendar_events: 10000, allocations: 10000, manual_actuals: 10000, goals: 1 };
  if (result.fixture !== 'p1-reference-scale-v1' || result.local_date !== localDate || !result.authored_fingerprint || !result.lease_id || JSON.stringify(result.counts) !== JSON.stringify(expected)) {
    throw new Error(`unexpected fixed fixture receipt: ${JSON.stringify(result)}`);
  }
  return { fixture: result.fixture, local_date: result.local_date, counts: result.counts, fingerprint: result.authored_fingerprint, lease_id: result.lease_id };
})()
